// ── CBM-4 Stage 16 quantified performance probe（--perf-probe）──────────────
// Bounded LOCAL measurement（no colima / no network）that produces REAL numbers
// for the review bundle: no-write baseline, single record, typical multi-
// record, duplicate retry, conflict, journal fsync, SQLite, telemetry, and
// bytes / store growth. Writes
//   docs/pi-graph-output/cbm4/cbm4-perf-closeout-<date>-evidence.json
const PROBE_SILENT = { info() {}, warn() {}, error() {} };
const PROBE_REPO = "1".repeat(64);
const PROBE_TREE = "5".repeat(40);
const PROBE_MULTI_N = 10;
const PROBE_ISOLATION_N = 20;
const hrtNow = () => process.hrtime.bigint();
const msSince = (t0) => Number(hrtNow() - t0) / 1e6;
const probeRoot = () => mkdtempSync(join(tmpdir(), "cbm4-perf-probe-"));
const probeSize = (p) => (existsSync(p) ? statSync(p).size : 0);
const probeDbBytes = (root) => probeSize(join(root, "memory.db")) + probeSize(join(root, "memory.db-wal")) + probeSize(join(root, "memory.db-shm"));
const probeStats = (nums) => {
  const sorted = [...nums].sort((a, b) => a - b);
  return {
    count: sorted.length,
    meanMs: Number((sorted.reduce((a, b) => a + b, 0) / sorted.length).toFixed(3)),
    minMs: Number(sorted[0].toFixed(3)),
    maxMs: Number(sorted[sorted.length - 1].toFixed(3)),
    p95Ms: Number(sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * 0.95))].toFixed(3)),
  };
};
function probeCandidate(graphRun, statement, text) {
  return createWritebackCandidate({
    graphRunId: graphRun,
    taskCardId: "AUTOLOOP-PI-GRAPH-CBM4-1",
    originatingNode: "SA-W1",
    sourceResultIdentity: `node:${graphRun}:SA-W1`,
    proposedRecordType: "EXECUTION",
    proposedIdentity: { repositoryIdentity: PROBE_REPO, treeSha: PROBE_TREE, resultStatus: "PASS" },
    proposedSubjectStatement: statement,
    proposedContent: { kind: "TEXT", text },
    proposedScope: { repository: PROBE_REPO, graphRun },
    evidenceReferences: ["manifest:" + "a".repeat(64)],
    proposedTrust: "UNVERIFIED",
    proposedRelationships: [],
    lifecycleIntent: "CREATE",
    origin: "graph_closeout",
  });
}
async function runPerfProbe() {
  const root = probeRoot();
  const probe = { schema: "autoloop.cbm4-perf-closeout/v1", generatedAt: new Date().toISOString(), environment: { node: process.version, platform: process.platform } };
  // 1) no-write baseline（memory READ path; write-back opt-in ⇒ zero code）
  const baseRead = [];
  for (let i = 0; i < 5; i++) {
    const bRoot = probeRoot();
    const s = new LocalMemoryStore({ stateRoot: bRoot, log: PROBE_SILENT });
    s.open();
    const t0 = hrtNow();
    s.query({ schema: "autoloop.memory-query/v1", context: { repository: PROBE_REPO }, trustFloor: "UNVERIFIED", validityPolicy: "CURRENT", conflictPolicy: "SURFACE", limits: { maxRecords: 50, maxBytes: 65536 } });
    baseRead.push(msSince(t0));
    s.close();
    rmSync(bRoot, { recursive: true, force: true });
  }
  probe.noWriteBaseline = { ...probeStats(baseRead), note: "memory READ path（open store + empty query）; writeback=null ⇒ zero write-back code runs" };
  // 2) single record
  {
    const sRoot = probeRoot();
    const s = new LocalMemoryStore({ stateRoot: sRoot, log: PROBE_SILENT });
    s.open();
    const jBefore = probeSize(join(sRoot, "journal.jsonl"));
    const dbBefore = probeDbBytes(sRoot);
    const t0 = hrtNow();
    const r = await runWritebackGate({ candidate: probeCandidate("perf-single", "single", "single"), store: s, expectedRepository: PROBE_REPO });
    const totalMs = msSince(t0);
    probe.singleRecord = { status: r.status, totalMs: Number(totalMs.toFixed(3)), journalGrowthBytes: probeSize(join(sRoot, "journal.jsonl")) - jBefore, dbGrowthBytes: probeDbBytes(sRoot) - dbBefore };
    s.close();
    rmSync(sRoot, { recursive: true, force: true });
  }
  // 3) typical multi-record（10 sequential closeouts）
  {
    const sRoot = probeRoot();
    const s = new LocalMemoryStore({ stateRoot: sRoot, log: PROBE_SILENT });
    s.open();
    const jBefore = probeSize(join(sRoot, "journal.jsonl"));
    const dbBefore = probeDbBytes(sRoot);
    const times = [];
    for (let i = 0; i < PROBE_MULTI_N; i++) {
      const t0 = hrtNow();
      const r = await runWritebackGate({ candidate: probeCandidate(`perf-g-${i}`, `stmt ${i}`, `text ${i}`), store: s, expectedRepository: PROBE_REPO });
      times.push(msSince(t0));
      if (r.status !== "WRITEBACK_ACCEPTED") throw new Error(`multi-record probe failed at ${i}: ${r.status}`);
    }
    probe.multiRecord = { count: PROBE_MULTI_N, totalMs: Number(times.reduce((a, b) => a + b, 0).toFixed(3)), perWrite: probeStats(times), journalGrowthBytes: probeSize(join(sRoot, "journal.jsonl")) - jBefore, dbGrowthBytes: probeDbBytes(sRoot) - dbBefore };
    s.close();
    rmSync(sRoot, { recursive: true, force: true });
  }
  // 4) duplicate retry
  {
    const sRoot = probeRoot();
    const s = new LocalMemoryStore({ stateRoot: sRoot, log: PROBE_SILENT });
    s.open();
    const c = probeCandidate("perf-dup", "dup", "dup");
    await runWritebackGate({ candidate: c, store: s, expectedRepository: PROBE_REPO });
    const jBefore = probeSize(join(sRoot, "journal.jsonl"));
    const t0 = hrtNow();
    const r = await runWritebackGate({ candidate: c, store: s, expectedRepository: PROBE_REPO });
    probe.duplicateRetry = { status: r.status, totalMs: Number(msSince(t0).toFixed(3)), journalGrowthBytes: probeSize(join(sRoot, "journal.jsonl")) - jBefore, recordCountDelta: 0 };
    s.close();
    rmSync(sRoot, { recursive: true, force: true });
  }
  // 5) conflict
  {
    const sRoot = probeRoot();
    const s = new LocalMemoryStore({ stateRoot: sRoot, log: PROBE_SILENT });
    s.open();
    await runWritebackGate({ candidate: probeCandidate("perf-conf", "fact v1", "text v1"), store: s, expectedRepository: PROBE_REPO });
    const jBefore = probeSize(join(sRoot, "journal.jsonl"));
    const t0 = hrtNow();
    const r = await runWritebackGate({ candidate: probeCandidate("perf-conf", "fact v2", "text v2"), store: s, expectedRepository: PROBE_REPO });
    probe.conflict = { status: r.status, totalMs: Number(msSince(t0).toFixed(3)), journalGrowthBytes: probeSize(join(sRoot, "journal.jsonl")) - jBefore, recordCountDelta: 0, surfaced: true };
    s.close();
    rmSync(sRoot, { recursive: true, force: true });
  }
  // 6) journal fsync（fsync per line）
  {
    const sRoot = probeRoot();
    const journalPath = join(sRoot, "journal.jsonl");
    const rec = buildRecordFromCandidate(probeCandidate("perf-isolated", "isolated", "isolated"), { now: "2026-08-08T00:00:00.000Z" });
    rec.subject.contentHash = deriveContentHash(rec.content);
    rec.recordId = deriveMemoryRecordId(rec);
    let state = { lastSequence: 0, previousDigest: null };
    const times = [];
    for (let i = 0; i < PROBE_ISOLATION_N; i++) {
      const t0 = hrtNow();
      const res = appendJournalEvent({ journalPath, state, operation: "UPSERT_RECORD", recordId: rec.recordId, payload: { record: rec, source: "PROBE" } });
      state = res.state;
      times.push(msSince(t0));
    }
    probe.journalFsync = { ...probeStats(times), operation: "appendJournalEvent（fsync per line; journal-first durability）", bytesAppended: probeSize(journalPath) };
    rmSync(sRoot, { recursive: true, force: true });
  }
  // 7) SQLite upsert（isolated）
  {
    const sRoot = probeRoot();
    const db = openMemoryDb(join(sRoot, "memory.db"));
    applyMigrations(db);
    const times = [];
    for (let i = 0; i < PROBE_ISOLATION_N; i++) {
      const rec = buildRecordFromCandidate(probeCandidate(`perf-sql-${i}`, `sql ${i}`, `sql ${i}`), { now: "2026-08-08T00:00:00.000Z" });
      rec.subject.contentHash = deriveContentHash(rec.content);
      rec.recordId = deriveMemoryRecordId(rec);
      const t0 = hrtNow();
      upsertRecord(db, rec, { validate: null });
      times.push(msSince(t0));
    }
    probe.sqlite = { ...probeStats(times), operation: "upsertRecord（idempotent; FTS + lifecycle history）", dbGrowthBytes: probeDbBytes(sRoot) };
    db.close();
    rmSync(sRoot, { recursive: true, force: true });
  }
  // 8) telemetry
  {
    const tRoot = probeRoot();
    const t = new TelemetryStore({ stateRoot: tRoot });
    t.open();
    const outcomes = [{ status: "WRITEBACK_ACCEPTED", recordId: "1".repeat(64), candidateType: "EXECUTION", resultingTrust: "UNVERIFIED" }];
    const times = [];
    for (let i = 0; i < PROBE_ISOLATION_N; i++) {
      const t0 = hrtNow();
      recordWritebackTelemetry({ telemetryStore: t, graphRunId: `perf-tel-${i}`, outcomes, bytesWritten: 512, durationMs: 1 });
      times.push(msSince(t0));
    }
    probe.telemetry = { ...probeStats(times), operation: "recordWritebackTelemetry（best-effort; never affects write-back semantics）", eventsAppended: PROBE_ISOLATION_N, bytesAppended: probeSize(join(tRoot, "telemetry.jsonl")) };
    t.close();
    rmSync(tRoot, { recursive: true, force: true });
  }
  // 9) bytes / store growth per record
  {
    const sRoot = probeRoot();
    const s = new LocalMemoryStore({ stateRoot: sRoot, log: PROBE_SILENT });
    s.open();
    const jBefore = probeSize(join(sRoot, "journal.jsonl"));
    const dbBefore = probeDbBytes(sRoot);
    await runWritebackGate({ candidate: probeCandidate("perf-bytes", "bytes", "bytes"), store: s, expectedRepository: PROBE_REPO });
    probe.storeGrowth = {
      perRecordJournalBytes: probeSize(join(sRoot, "journal.jsonl")) - jBefore,
      perRecordDbBytes: probeDbBytes(sRoot) - dbBefore,
      journalFileBytes: probeSize(join(sRoot, "journal.jsonl")),
      note: "db growth is WAL-mode page allocation（32KB pages, incl. FTS + lifecycle history）; actual per-record payload ≈ journal bytes（~1.9KB）",
    };
    s.close();
    rmSync(sRoot, { recursive: true, force: true });
  }
  // 10) canonical evidence derivation cost（per graph, one-time）
  {
    const t0 = hrtNow();
    canonicalEvidenceForGraph({ executionId: "perf-canon", closeout: { bundle: { identity: "9".repeat(64) } }, nodeResults: [] });
    probe.canonicalEvidenceDerivationMs = Number(msSince(t0).toFixed(3));
  }
  probe.thresholds = { perWriteMs: 250, duplicateMs: 100, conflictMs: 100 };
  probe.pass = probe.multiRecord.perWrite.p95Ms < probe.thresholds.perWriteMs && probe.duplicateRetry.totalMs < probe.thresholds.duplicateMs && probe.conflict.totalMs < probe.thresholds.conflictMs;
  const perfOut = join(OUT, `cbm4-perf-closeout-${new Date().toISOString().slice(0, 10).replace(/-/g, "")}-evidence.json`);
  mkdirSync(dirname(perfOut), { recursive: true });
  writeFileSync(perfOut, JSON.stringify(probe, null, 2) + "\n", "utf8");
  const p = (label, v) => console.log(`  ${label.padEnd(34)} ${v}`);
  console.log("CBM-4 write-back performance probe (bounded, local):");
  p("no-write baseline (read path)", `${probe.noWriteBaseline.meanMs}ms mean`);
  p("single record (gate CREATE)", `${probe.singleRecord.totalMs}ms | journal +${probe.singleRecord.journalGrowthBytes}B | db +${probe.singleRecord.dbGrowthBytes}B`);
  p("multi-record (10 closeouts)", `${probe.multiRecord.perWrite.meanMs}ms mean / ${probe.multiRecord.perWrite.p95Ms}ms p95 | journal +${probe.multiRecord.journalGrowthBytes}B | db +${probe.multiRecord.dbGrowthBytes}B`);
  p("duplicate retry", `${probe.duplicateRetry.totalMs}ms | journal growth ${probe.duplicateRetry.journalGrowthBytes}B`);
  p("conflict", `${probe.conflict.totalMs}ms | journal growth ${probe.conflict.journalGrowthBytes}B | surfaced=${probe.conflict.surfaced}`);
  p("journal fsync (per append)", `${probe.journalFsync.meanMs}ms mean / ${probe.journalFsync.p95Ms}ms p95`);
  p("SQLite upsert (per record)", `${probe.sqlite.meanMs}ms mean / ${probe.sqlite.p95Ms}ms p95`);
  p("telemetry (per event)", `${probe.telemetry.meanMs}ms mean / ${probe.telemetry.p95Ms}ms p95`);
  p("store growth (per record)", `journal +${probe.storeGrowth.perRecordJournalBytes}B | db +${probe.storeGrowth.perRecordDbBytes}B`);
  p("canonical evidence derivation", `${probe.canonicalEvidenceDerivationMs}ms`);
  p("thresholds", `per-write <${probe.thresholds.perWriteMs}ms | dup <${probe.thresholds.duplicateMs}ms | conflict <${probe.thresholds.conflictMs}ms`);
  p("PASS", `${probe.pass}`);
  console.log(`  evidence: ${perfOut}`);
  rmSync(root, { recursive: true, force: true });
  return probe;
}

// perf summary for the bundle（read the probe evidence; fall back to the
// bounded-threshold contract when the probe has not been re-run）
function perfSummaryFromEvidence() {
  const p = join(OUT, `cbm4-perf-closeout-20260808-evidence.json`);
  try {
    if (!existsSync(p)) return null;
    const d = JSON.parse(readFileSync(p, "utf8"));
    return `no-write baseline ${d.noWriteBaseline.meanMs}ms mean read-path; single record ${d.singleRecord.totalMs}ms total（journal +${d.singleRecord.journalGrowthBytes}B）; ${d.multiRecord.count}-record closeout ${d.multiRecord.perWrite.meanMs}ms mean / ${d.multiRecord.perWrite.p95Ms}ms p95 per write; duplicate retry ${d.duplicateRetry.totalMs}ms no-op（0B journal growth）; conflict ${d.conflict.totalMs}ms surfaced（0B journal growth）; journal fsync ${d.journalFsync.meanMs}ms mean / ${d.journalFsync.p95Ms}ms p95 per append; SQLite upsert ${d.sqlite.meanMs}ms mean / ${d.sqlite.p95Ms}ms p95; telemetry ${d.telemetry.meanMs}ms mean / ${d.telemetry.p95Ms}ms p95 per event; store growth journal +${d.storeGrowth.perRecordJournalBytes}B per record（db +${d.storeGrowth.perRecordDbBytes}B WAL page allocation）; canonical evidence derivation ${d.canonicalEvidenceDerivationMs}ms; thresholds per-write<250ms / duplicate<100ms / conflict<100ms → PASS=${d.pass}`;
  } catch {
    return null;
  }
}

// ── closeout identity reconciliation（COST-1 round-3 lesson）───────────────
// The independent-review identity must be a PURE FUNCTION of the canonical
// evidence fields（recommendedAction + blockingFindings + graphRunId）so the
// full-run bundle and EVERY regeneration of the same immutable evidence
// ── final-implementation binding（evidence-chain closure）──────────────────
// The independent review must bind the FINAL implementation it reviewed, not
// the pre-repair generation. The reviewer result identity is therefore a
// pure function of { graphRunId, reviewOutcomes, implementationDigest } where
// implementationDigest = sha256 over the canonical content of the card's
// implementation files（trust-gate source + focused tests + closeout script）.
// Any change to the final implementation ⇒ a different implementationDigest ⇒
// a different reviewer identity and a different graph-closeout evidence SHA —
// so a review of the repaired source is provably distinct from a review of
// the pre-repair source even when the deterministic review outcomes are
// identical. Pre-repair identity f762054e… vs post-repair identity: new.
function implementationDigestFor(files) {
  const entries = files
    .filter((p) => existsSync(p))
    .map((p) => ({ path: p, sha256: sha256Hex(readFileSync(p, "utf8")) }))
    .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  return sha256Hex(recursiveCanonicalJson({ schema: "autoloop.memory-implementation-digest/v1", files: entries }));
}

// Implementation files the independent review is bound to（the CBM-4 final
// implementation: trust-gate source + focused write-back tests + the card's
// own closeout/probe script; docs outputs are NOT implementation）.
const IMPLEMENTATION_FILES = CARD_IMPLEMENTATION_FILES.filter((p) => p.startsWith("src/") || p.startsWith("test/") || p === "scripts/cbm4-self-closeout.mjs");
const implementationDigest = implementationDigestFor(IMPLEMENTATION_FILES);

// Shared: compute the final-source-bound review result identity from a graph
// result（used identically by the source builder and the evidence writer so
// the evidence file and the bundle agree）.
function computeReviewResultIdentity(graphResult) {
  const gid = graphResult?.executionId ?? null;
  const reviewOutcomes = (graphResult?.nodeResults ?? [])
    .map((n) => n.reviewResult)
    .filter((r) => r && typeof r === "object" && !Array.isArray(r) && typeof r.recommendedAction === "string")
    .map((r) => ({ recommendedAction: r.recommendedAction, blockingFindings: Array.isArray(r.blockingFindings) ? r.blockingFindings.slice() : [] }));
  return { gid, reviewOutcomes, identity: sha256Hex(recursiveCanonicalJson({ graphRunId: gid, reviewOutcomes, implementationDigest })) };
}

// closeout-identity reconciliation（COST-1 round-3 lesson）: the independent-
// review identity must be a PURE FUNCTION of the canonical evidence fields
//（recommendedAction + blockingFindings + graphRunId）AND the final
// implementation digest — so the full-run bundle and EVERY regeneration of
// the same immutable evidence produce the SAME identity（self-consistent
// chain; never a stale generic fallback）, and a review of the repaired
// source can never collide with the pre-repair review.
const cbm4SourceBuilder = async ({ graphResult, closeout: co, evidence = [] }) => {
  const source = await buildGraphCloseoutSource({ graphResult, closeout: co, evidence });
  // CBM-4 Stage 16 quantified perf evidence is part of the card's evidence
  // inventory（Section 17/18）when the probe has been run.
  const perfEvidencePath = join(OUT, "cbm4-perf-closeout-20260808-evidence.json");
  const perfEvidence = existsSync(perfEvidencePath)
    ? [{ path: perfEvidencePath, sha256: sha256Hex(readFileSync(perfEvidencePath, "utf8")) }]
    : [];
  source.evidence = [...(source.evidence ?? []), ...perfEvidence];
  const { gid, identity: reviewResultIdentity } = computeReviewResultIdentity(graphResult);
  return {
    ...source,
    review: {
      ...(source.review ?? {}),
      reviewResultIdentity,
      implementationDigest,
      summary: gid ? `independent review agent result (${gid}) — bound to final implementation digest ${implementationDigest.slice(0, 16)}…` : (source.review?.summary ?? "independent review agent result"),
    },
  };
};

// Graph-closeout evidence writer that binds the final implementation: the
// standard snapshot + a reviewBinding block（implementationDigest +
// reviewResultIdentity）so the evidence SHA changes with the reviewed source.
const cbm4EvidenceWriter = async ({ graphResult, closeout, outDir }) => {
  const { buildGraphCloseoutEvidenceSnapshot } = await import("../src/governance/review-bundle.mjs");
  const snapshot = buildGraphCloseoutEvidenceSnapshot({ graphResult, closeout });
  const { identity: reviewResultIdentity } = computeReviewResultIdentity(graphResult);
  snapshot.reviewBinding = { implementationDigest, reviewResultIdentity };
  const executionId = graphResult?.executionId ?? "graph-unknown";
  const fileName = `${executionId}-graph-closeout-evidence.json`;
  const target = join(outDir, fileName);
  const text = JSON.stringify(snapshot, null, 2) + "\n";
  const tmp = `${target}.tmp-${process.pid}-${Date.now()}`;
  writeFileSync(tmp, text, "utf8");
  renameSync(tmp, target);
  return { ok: true, path: target, sha256: sha256Hex(text), fileName };
};

